mapper.select:
SELECT MDPCR.BASEYMD ,MDPCR.TIMEZN ,MDPCR.CELL_500 ,MDPCR.FLT_POP ,MDPCR.ETL_DT ,KCMI.CITY_CD FROM MRT_DYNMC_POPLTN_CELL500_RSLT MDPCR INNER JOIN ( SELECT KCMI.CELL_500_ID,KCMI.CITY_CD FROM KT_CELL_MAPN_INFO KCMI GROUP BY KCMI.CELL_500_ID,KCMI.CITY_CD ) KCMI ON KCMI.CELL_500_ID = MDPCR.CELL_500 WHERE 1=1
AND TO_CHAR(TO_DATE(MDPCR.BASEYMD, 'YYYYMMDD'), 'YYYY') = #{searchYear}
AND TO_CHAR(TO_DATE(MDPCR.BASEYMD, 'YYYYMMDD'), 'YYYY-MM-DD') = #{startDate}
AND KCMI.CITY_CD||'0' = #{searchLocation}

SELECT MDPCR.BASEYMD ,MDPCR.TIMEZN ,SUM(MDPCR.FLT_POP) as FLT_POP ,KCMI.CITY_CD FROM MRT_DYNMC_POPLTN_CELL500_RSLT MDPCR INNER JOIN ( SELECT KCMI.CELL_500_ID,KCMI.CITY_CD FROM KT_CELL_MAPN_INFO KCMI GROUP BY KCMI.CELL_500_ID,KCMI.CITY_CD ) KCMI ON KCMI.CELL_500_ID = MDPCR.CELL_500 WHERE 1=1
AND TO_CHAR(TO_DATE(MDPCR.BASEYMD, 'YYYYMMDD'), 'YYYY') = #{searchYear}
AND TO_CHAR(TO_DATE(MDPCR.BASEYMD, 'YYYYMMDD'), 'YYYY-MM-DD') = #{startDate}
AND KCMI.CITY_CD||'0' = #{searchLocation}
GROUP BY MDPCR.BASEYMD ,MDPCR.TIMEZN,KCMI.CITY_CD
